/* ── Aero Gloss Shine Sweep ─────────────────────────────── */


/* Apply shine sweep to all blue pill buttons on hover */
html[data-ypp-ui-design="frutiger-aero"] ytd-watch-metadata #actions yt-button-shape > *::before,
html[data-ypp-ui-design="frutiger-aero"] .yt-spec-button-shape-next--call-to-action::before,
