/* ── ui-style: origami ── */




@keyframes origami-pulse {
  0% { 
    box-shadow: 2px 2px 10px rgba(0,0,0,0.1);
  }
  50% {
    box-shadow: 5px 5px 18px rgba(0,0,0,0.18);
  }
  100% {
    box-shadow: 2px 2px 10px rgba(0,0,0,0.1);
  }
}

@keyframes sepia-bloom {
  0% { 
    filter:brightness(1);
  }
  100% {
    filter:brightness(1.1) saturate(1.1);
  }
}/* Unique Shapes and Patterns for origami */

